pairing.imported-two-readings-capacities:
"""pairing.imported-two-readings-capacities-vacuum-null: exact checks (GA.py, Fractions and Gaussian
rationals GA.QI).

(1) Witt basis = CAR: for every signature with 2 <= n <= 6 a Witt basis is built from real hyperbolic
    pairs w = (e_i + e_j)/2, w' = (e_i - e_j)/2 (e_i^2 = +1, e_j^2 = -1) and complex pairs
    (e_a + i e_b)/2, -+(e_a - i e_b)/2 from two generators of one sign; in Cl(p,q) (x) C the relation
    {e_a, e_b} = 2 g_ab becomes {w_k, w_l} = {w'_k, w'_l} = 0, {w_k, w'_l} = delta_kl, with
    floor(n/2) modes. For (1,3): one real pair and one complex pair (the Dirac spinor as two modes).
(2) Capacities: the real isotropic W spanned by min(p,q) vectors e_i + e_{p+i} has W-perp of
    signature (p - m, q - m, m), m = min(p,q), so W-perp/W is definite and W is maximal: real capacity
    min(p,q). Over C, the isotropic W_C of the floor(n/2) creation vectors has W_C-perp/W_C of
    dimension n - 2 floor(n/2) <= 1 with a nonzero form, so it is maximal: complex capacity floor(n/2).
    For (1,3) these are 1 and 2.
(3) Purity for 2 nu <= 6: on the Fock space of nu modes (Jordan-Wigner over Q(i)), the annihilator
    {x in V_C : x s = 0} of a parity-definite state s, an exact kernel over Q(i), has dimension nu for
    every sample state at nu = 2 and nu = 3 (both parities, generic and special), so each is the
    vacuum of a Witt decomposition; at nu = 4 the even state |0> + |1234> has annihilator 0 (not pure)
    while |0> has 4: the bound 2 nu <= 6 is sharp.
The claim collects these from stored results; each function calls premise() for the result whose
statement it tests (two-presentations, the capacity theorem and its consequences, Cartan's purity
theorem). The clause that a vacuum is an extra
datum (a null direction to be supplied) is a reading and is not computed.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

QI = GA.QI


def cvec(n, coeffs):
    return {(i,): QI(c) if not isinstance(c, QI) else c for i, c in coeffs.items()}


def cadd(*xs):
    out = {}
    for x in xs:
        for b, c in x.items():
            out[b] = out.get(b, QI(0)) + c
    return {b: c for b, c in out.items() if c}


def cmul(x, y, sq):
    out = {}
    for b1, c1 in x.items():
        for b2, c2 in y.items():
            s, b = GA.blade_mul(b1, b2, sq)
            c = c1 * c2 * QI(s)
            if c:
                out[b] = out.get(b, QI(0)) + c
    return {b: c for b, c in out.items() if c}


def anti(x, y, sq):
    return cadd(cmul(x, y, sq), cmul(y, x, sq))


def witt_basis(p, q):
    """List of (w, w') pairs: real hyperbolic pairs first, then complex pairs."""
    pos, neg = list(range(p)), list(range(p, p + q))
    pairs = []
    while pos and neg:
        i, j = pos.pop(0), neg.pop(0)
        pairs.append((cvec(0, {i: F(1, 2), j: F(1, 2)}), cvec(0, {i: F(1, 2), j: F(-1, 2)})))
    for grp, sgn in ((pos, 1), (neg, -1)):
        while len(grp) >= 2:
            a, b = grp.pop(0), grp.pop(0)
            w = cvec(0, {a: QI(F(1, 2)), b: QI(0, F(1, 2))})
            wp = cvec(0, {a: QI(F(sgn, 2)), b: QI(0, F(-sgn, 2))})
            pairs.append((w, wp))
    return pairs


def check_witt_basis_relations_are_the_car():
    premise("one-relation.two-presentations")
    ok = True
    for n in range(2, 7):
        for p in range(n + 1):
            q = n - p
            sq = GA.sig(p, q)
            pairs = witt_basis(p, q)
            ok = ok and len(pairs) == n // 2
            for k, (wk, wpk) in enumerate(pairs):
                for l, (wl, wpl) in enumerate(pairs):
                    ok = ok and anti(wk, wl, sq) == {} and anti(wpk, wpl, sq) == {}
                    want = {(): QI(1)} if k == l else {}
                    ok = ok and anti(wk, wpl, sq) == want
    p13 = witt_basis(1, 3)
    real13 = [all(c.im == 0 for c in w.values()) for w, wp in p13]
    ok = ok and real13 == [True, False]
    GA.check("Witt bases give the CAR with floor(n/2) modes (n <= 6); (1,3): one real and one complex pair", ok)
    return ok


def check_real_and_complex_capacities():
    premise("tower.witt-index-quantum-capacity")
    premise("one-relation.two-capacities-three-consequences")
    ok = True
    for n in range(2, 7):
        for p in range(n + 1):
            q = n - p
            sq = GA.sig(p, q)
            mcap = min(p, q)
            W = []
            for i in range(mcap):
                v = [F(0)] * n
                v[i], v[p + i] = F(1), F(1)
                W.append(v)
            if W:
                rows = [[sq[k] * v[k] for k in range(n)] for v in W]
                perp = GA.field_kernel(rows)
            else:
                perp = [[F(1) if i == j else F(0) for i in range(n)] for j in range(n)]
            gram = [[sum(sq[k] * a[k] * b[k] for k in range(n)) for b in perp] for a in perp]
            ok = ok and all(sum(sq[k] * v[k] * v[k] for k in range(n)) == 0 for v in W)
            ok = ok and GA.congruence_signature(gram) == (p - mcap, q - mcap, mcap)
            # complex: W_C spanned by the w's of the Witt basis
            ccap = n // 2
            Wc = [[w.get((k,), QI(0)) for k in range(n)] for w, wp in witt_basis(p, q)]
            ok = ok and len(Wc) == ccap
            rows = [[QI(sq[k]) * v[k] for k in range(n)] for v in Wc]
            perp = GA.field_kernel(rows)
            ok = ok and len(perp) == n - ccap
            gram = [[sum((QI(sq[k]) * a[k] * b[k] for k in range(n)), QI(0)) for b in perp] for a in perp]
            ok = ok and GA.field_rank(gram) == n - 2 * ccap
    ok = ok and (min(1, 3), (1 + 3) // 2) == (1, 2)
    GA.check("real capacity min(p,q) and complex capacity floor(n/2): maximal isotropic subspaces (n <= 6)", ok)
    return ok


def fock(nu):
    d = 2 ** nu
    a = []
    for j in range(nu):
        M = [[QI(0)] * d for _ in range(d)]
        for s in range(d):
            if (s >> j) & 1:
                sign = -1 if bin(s & ((1 << j) - 1)).count("1") % 2 else 1
                M[s & ~(1 << j)][s] = QI(sign)
        a.append(M)
    ad = [[[M[c][r].conj() for c in range(d)] for r in range(d)] for M in a]
    return a, ad


def apply(M, v):
    return [sum((M[i][k] * v[k] for k in range(len(v))), QI(0)) for i in range(len(M))]


def annihilator_dim(nu, state):
    a, ad = fock(nu)
    cols = [apply(M, state) for M in a + ad]
    M = [[cols[k][i] for k in range(2 * nu)] for i in range(len(state))]
    return 2 * nu - GA.field_rank(M)


STATES = {
    2: [{0: QI(1)}, {3: QI(1)}, {0: QI(2, -1), 3: QI(3, 1)}, {1: QI(1)}, {1: QI(1, 2), 2: QI(-3, 1)}],
    3: [{0: QI(1)}, {0: QI(1), 3: QI(2), 5: QI(-1, 1), 6: QI(0, 3)}, {3: QI(1), 6: QI(2, 1)},
        {1: QI(1), 2: QI(-2), 4: QI(1, 1), 7: QI(3, -2)}, {7: QI(1)}, {3: QI(1), 5: QI(1), 6: QI(1)}],
}


def vecstate(nu, d):
    return [d.get(i, QI(0)) for i in range(2 ** nu)]


def check_every_weyl_spinor_pure_up_to_six():
    premise("one-relation.imported-cartans-purity-theorem-thouless-form")
    ok = True
    for nu, states in STATES.items():
        for st in states:
            parities = {bin(i).count("1") % 2 for i in st}
            ok = ok and len(parities) == 1
            ok = ok and annihilator_dim(nu, vecstate(nu, st)) == nu
    ok = ok and annihilator_dim(4, vecstate(4, {0: QI(1), 15: QI(1)})) == 0
    ok = ok and annihilator_dim(4, vecstate(4, {0: QI(1)})) == 4
    GA.check("every parity-definite state is pure (annihilator of dimension nu) at nu = 2, 3; not at nu = 4", ok)
    return ok

pairing.loop-classes-are-weyl-components:
"""pairing.loop-classes-are-weyl-components: exact checks.

The vacuum curvature operators at a point are the algebraic Weyl maps of Cl(1,3) (GA.py, (+,-,-,-)): the
10-dimensional exact kernel of symmetry, Ricci trace-freeness d_a . W(a ^ b) = 0 and first Bianchi; for a
vacuum field calR = W. The loop bivector is R(u, v) = -calR(u ^ v) (LDG sign) and
C(u, v, w, z) = <R(u, v) . w, z>, complex-bilinear (Gaussian rationals). Unit tetrad l = e0 + e1,
n = (e0 - e1)/2 (l . n = 1), m = (e2 + i e3)/sqrt 2 (m . mbar = -1); computed with m0 = e2 + i e3 and the
powers of sqrt 2 cleared, so every identity below is exact. Psi0 = C(l, m, l, m), Psi1 = C(l, n, l, m),
Psi2 = C(l, m, mbar, n), as in the premise Fact. Computed:
(1) on all 10 basis Weyl maps and on a generic combination: the classes C(u, v, l, m) of the six tetrad
    loops are Psi0, 0, -Psi1, Psi1, 0, -Psi2 for (l, m), (l, mbar), (m, mbar), (l, n), (n, m), (n, mbar);
(2) on the Weyl space, the joint kernel of the three null-cone classes ((l, m), (l, mbar), (m, mbar)) equals
    that of {Psi0, Psi1} (both of real codimension 4), and on it the (l, n) and (n, m) classes vanish and
    the (n, mbar) class is -Psi2;
(3) the Schwarzschild operator (M/2r^3)(B + 3 sigma_r B sigma_r) (store sign; sigma_r = e0 e1 the radial
    plane) is a Weyl map with Psi0 = Psi1 = Psi3 = Psi4 = 0 and Psi2 = -M/r^3 in the unit tetrad, so l is a
    repeated principal null direction and every loop in its null cone has zero class.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


# ---- algebraic Weyl maps on the bivectors of a four-dimensional signature (exact) ----
BLADES2 = [(a, b) for a in range(4) for b in range(a + 1, 4)]


def wop(X, B, sq):
    """Apply the bivector map with matrix X (X[i][j] = blade_i coefficient of W(blade_j)) to bivector B."""
    out = {}
    for j, bl in enumerate(BLADES2):
        c = B.get(bl, F(0))
        if c:
            out = GA.add(out, {BLADES2[i]: c * X[i][j] for i in range(6) if X[i][j]})
    return out


def wedge_vb(a, B, sq):
    return {k: v for k, v in GA.scal(F(1, 2), GA.add(GA.mul(a, B, sq), GA.mul(B, a, sq))).items() if len(k) == 3}


def dot_vb(a, B, sq):
    return {k: v for k, v in GA.scal(F(1, 2), GA.sub(GA.mul(a, B, sq), GA.mul(B, a, sq))).items() if len(k) == 1}


def weyl_constraints(X, sq):
    """Linear constraints of an algebraic Weyl map: symmetry, Ricci trace-free, first Bianchi."""
    rows = []
    for i in range(6):
        for j in range(i + 1, 6):
            A, B = {BLADES2[i]: F(1)}, {BLADES2[j]: F(1)}
            rows.append(GA.mul(A, wop(X, B, sq), sq).get((), F(0)) - GA.mul(wop(X, A, sq), B, sq).get((), F(0)))
    for nu in range(4):
        tr, bi = {}, {}
        for mu in range(4):
            if mu == nu:
                continue
            Bmn = GA.mul(GA.gen(mu), GA.gen(nu), sq)
            WB = wop(X, Bmn, sq)
            recip = GA.scal(F(1) / sq[mu], GA.gen(mu))
            tr = GA.add(tr, dot_vb(recip, WB, sq))
            bi = GA.add(bi, wedge_vb(recip, WB, sq))
        rows.extend(tr.get((k,), F(0)) for k in range(4))
        rows.extend(bi.get(t, F(0)) for t in [(0, 1, 2), (0, 1, 3), (0, 2, 3), (1, 2, 3)])
    return rows


def weyl_space(sq):
    """Basis of the algebraic Weyl maps (6 x 6 matrices) of the signature sq, by an exact kernel."""
    cols = []
    for i in range(6):
        for j in range(6):
            X = [[F(1) if (a, b) == (i, j) else F(0) for b in range(6)] for a in range(6)]
            cols.append(weyl_constraints(X, sq))
    mat = [list(r) for r in zip(*cols)]
    return [[[v[6 * i + j] for j in range(6)] for i in range(6)] for v in GA.field_kernel(mat)]


def op_matrix(fn):
    """6 x 6 matrix of a bivector map given as a function on Fraction bivectors."""
    cols = [fn({bl: F(1)}) for bl in BLADES2]
    return [[cols[j].get(BLADES2[i], F(0)) for j in range(6)] for i in range(6)]


S = GA.sig(1, 3)
E = [GA.gen(i) for i in range(4)]
LV = (GA.add(E[0], E[1]), {})
NV2 = (GA.scal(F(1, 2), GA.sub(E[0], E[1])), {})
M0 = (E[2], E[3])
MB0 = (E[2], GA.neg(E[3]))
GENERIC = [F(3), F(-1), F(2), F(1, 2), F(5), F(-4), F(1), F(7, 3), F(-2), F(1, 5)]
SCHW_K = [F(1, 8), F(-27, 2), F(4, 125)]                      # M/r^3 at sample points


def cwedge(u, v):
    def w(a, b):
        return GA.scal(F(1, 2), GA.sub(GA.mul(a, b, S), GA.mul(b, a, S)))
    return (GA.sub(w(u[0], v[0]), w(u[1], v[1])), GA.add(w(u[0], v[1]), w(u[1], v[0])))


def cdot(B, v):
    def d(Bx, a):
        return {k: c for k, c in GA.scal(F(1, 2), GA.sub(GA.mul(Bx, a, S), GA.mul(a, Bx, S))).items() if len(k) == 1}
    return (GA.sub(d(B[0], v[0]), d(B[1], v[1])), GA.add(d(B[0], v[1]), d(B[1], v[0])))


def cip(u, v):
    return GA.QI(GA.dot(u[0], v[0], S) - GA.dot(u[1], v[1], S), GA.dot(u[0], v[1], S) + GA.dot(u[1], v[0], S))


def C(X, u, v, w, z):
    B = cwedge(u, v)
    R = (GA.neg(wop(X, B[0], S)), GA.neg(wop(X, B[1], S)))
    return cip(cdot(R, w), z)


def scalars(X):
    """Classes and Weyl scalars with m = m0/sqrt 2, each multiplied by the power of sqrt 2 that clears it:
    returned values are exact; e.g. 'mmb' = 2 sqrt2 class(m, mbar), 'P1' = sqrt2 Psi1."""
    return {"lm": C(X, LV, M0, LV, M0), "P0": C(X, LV, M0, LV, M0),
            "lmb": C(X, LV, MB0, LV, M0), "mmb": C(X, M0, MB0, LV, M0),
            "ln": C(X, LV, NV2, LV, M0), "P1": C(X, LV, NV2, LV, M0),
            "nm": C(X, NV2, M0, LV, M0), "nmb": C(X, NV2, MB0, LV, M0), "P2": C(X, LV, M0, MB0, NV2),
            "P3": C(X, LV, NV2, MB0, NV2), "P4": C(X, NV2, MB0, NV2, MB0)}


def table_holds(X):
    s = scalars(X)
    return (s["lm"] == s["P0"] and s["lmb"] == 0 and s["mmb"] == -2 * s["P1"] and s["ln"] == s["P1"]
            and s["nm"] == 0 and s["nmb"] == -s["P2"])


def check_six_loop_classes():
    premise("pairing.imported-weyl-scalars-petrov-type-schwarzschild")
    premise("synthesis.imported-gtg-dictionary")
    Ws = weyl_space(S)
    gen = [[sum(c * X[i][j] for c, X in zip(GENERIC, Ws)) for j in range(6)] for i in range(6)]
    ok = len(Ws) == 10 and all(table_holds(X) for X in Ws) and table_holds(gen)
    s = scalars(gen)
    _tp_rv = (ok and s["P0"] != 0 and s["P1"] != 0 and s["P2"] != 0); assert _tp_rv is not False, "check_six_loop_classes"; return _tp_rv


def check_null_cone_classes_vanish_iff_repeated_pnd():
    premise("pairing.imported-weyl-scalars-petrov-type-schwarzschild")
    Ws = weyl_space(S)
    S_all = [scalars(X) for X in Ws]

    def rows(keys):
        out = []
        for k in keys:
            out.append([s[k].re for s in S_all])
            out.append([s[k].im for s in S_all])
        return out
    cone, psi = rows(["lm", "lmb", "mmb"]), rows(["P0", "P1"])
    ok = GA.field_rank(cone) == 4 and GA.field_rank(psi) == 4 and GA.field_rank(cone + psi) == 4
    ker = GA.field_kernel(cone)
    ok = ok and len(ker) == 6
    for v in ker:
        X = [[sum(c * W[i][j] for c, W in zip(v, Ws)) for j in range(6)] for i in range(6)]
        s = scalars(X)
        ok = ok and s["ln"] == 0 and s["nm"] == 0 and s["nmb"] == -s["P2"] and s["P0"] == 0 and s["P1"] == 0
    _tp_rv = (ok); assert _tp_rv is not False, "check_null_cone_classes_vanish_iff_repeated_pnd"; return _tp_rv


def check_schwarzschild_type_d():
    premise("pairing.imported-weyl-scalars-petrov-type-schwarzschild")
    ok = True
    sig_r = GA.mul(E[0], E[1], S)
    for k in SCHW_K:
        X = op_matrix(lambda B: GA.scal(k / 2, GA.add(B, GA.scal(3, GA.mul(GA.mul(sig_r, B, S), sig_r, S)))))
        ok = ok and all(c == 0 for c in weyl_constraints(X, S))
        s = scalars(X)
        ok = ok and s["P0"] == 0 and s["P1"] == 0 and s["P3"] == 0 and s["P4"] == 0
        ok = ok and s["P2"] == GA.QI(-2 * k)                # 2 Psi2 (two factors of m) = -2 M/r^3
        ok = ok and s["lm"] == 0 and s["lmb"] == 0 and s["mmb"] == 0 and table_holds(X)
    _tp_rv = (ok); assert _tp_rv is not False, "check_schwarzschild_type_d"; return _tp_rv
